// Reads the static config (mounted read-only at /config) and the
// pipeline's persisted state (seen items + last run time + per-channel
// Telegram fetch times, under /data). State won't exist on the very
// first run — default it instead of failing.
//
// is_backfill comes from whichever trigger branch fed this node ("Mark as
// Scheduled" -> false, "Mark as Backfill" -> true) — see those two nodes.
const fs = require('fs');
const isBackfill = items[0].json.is_backfill === true;

const config = JSON.parse(fs.readFileSync('/config/config.json', 'utf8'));

let state;
try {
  state = JSON.parse(fs.readFileSync('/data/state.json', 'utf8'));
} catch (e) {
  state = { seen_ids: [], last_run_at: null, telegram_last_fetch: {} };
}

return [{ json: { config, state, is_backfill: isBackfill } }];

// Fetches every enabled source from config.sources — no source is
// hardcoded here. RSS feeds are fetched and parsed with a small regex
// parser (title/link/guid/pubDate/description/content:encoded); Telegram
// channels are read from their public https://t.me/s/<channel> preview
// (no login) and parsed out of the HTML. "email" sources are schema-only —
// not implemented yet.
//
// Each source is wrapped in its own try/catch: one feed being down or one
// channel's HTML changing shape never aborts the run for the others. Every
// source's outcome (items fetched, or its error) is recorded in
// source_results for the run log, regardless of success or failure.
//
// Normal (scheduled) mode: single preview page per Telegram channel, at
// most once every 24h per channel — unchanged from before backfill mode
// was added. Backfill mode (is_backfill: true): the 24h throttle doesn't
// apply, and Telegram channels are paginated backward with ?before=
// (capped at 5 pages per channel) until the configured backfill_days
// window is covered.
const config = items[0].json.config;
const state = items[0].json.state;
const isBackfill = items[0].json.is_backfill === true;
const now = Date.now();
const TELEGRAM_FETCH_INTERVAL_MS = 24 * 3600 * 1000;
const backfillDays = config.eval?.backfill_days ?? 30;
const backfillCutoff = new Date(now - backfillDays * 24 * 3600 * 1000);

function stripHtml(html) {
  return String(html || '').replace(/<[^>]+>/g, ' ');
}

function decodeEntities(text) {
  const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' };
  return String(text || '')
    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(parseInt(dec, 10)))
    .replace(/&(amp|lt|gt|quot|apos|nbsp);/g, (_, name) => named[name]);
}

function cleanText(html) {
  return decodeEntities(stripHtml(html)).replace(/\s+/g, ' ').trim();
}

function extractTag(block, tag) {
  const m = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
  if (!m) return '';
  const cdata = m[1].match(/^<!\[CDATA\[([\s\S]*)\]\]>$/);
  return cdata ? cdata[1] : m[1];
}

// --- RSS: fetch + parse with a tiny regex-based parser (no library) ---
// Unchanged by backfill mode — RSS feeds expose no pagination, so this is
// simply whatever the feed currently has, capped to max_items.
async function fetchRss(src) {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: src.url,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
  if (response.statusCode < 200 || response.statusCode >= 300) {
    throw new Error(`HTTP ${response.statusCode}`);
  }

  const xml = String(response.body);
  // RSS lists newest-first — cap to the first max_items blocks.
  const itemBlocks = (xml.match(/<item\b[\s\S]*?<\/item>/gi) || []).slice(0, src.max_items || 20);

  return itemBlocks.map((block) => {
    const title = cleanText(extractTag(block, 'title'));
    const link = extractTag(block, 'link').trim();
    const guidRaw = extractTag(block, 'guid').trim();
    const pubDateRaw = extractTag(block, 'pubDate').trim();
    const description = cleanText(extractTag(block, 'description'));
    const contentEncoded = cleanText(extractTag(block, 'content:encoded'));

    const body = contentEncoded || description;
    const combined = description && !body.startsWith(description.slice(0, 40))
      ? `${description} — ${body}`
      : body;

    return {
      title: title || '(untitled)',
      link: link || guidRaw,
      guid: link || guidRaw,
      pub_date: pubDateRaw ? new Date(pubDateRaw).toISOString() : null,
      snippet: combined.slice(0, 600),
      source_id: src.id,
      source_name: src.name,
      language: src.language
    };
  });
}

// --- Telegram: public preview HTML, parsed with regex (no library) ---
// Known Telegram CTA/signature boilerplate this project's channels use —
// a heuristic denylist, not exhaustive (same spirit as scripts/check-secrets.sh).
const TG_BOILERPLATE_MARKERS = [
  'Присоединяйтесь к нашему сообществу',
  'Присоединяйся к нашему сообществу',
  'Делаем музыкальную индустрию понятнее',
  'Больше новостей музыкальной индустрии',
  'Подписывайся на канал',
  'Подпишись на канал',
  'Подписаться на канал'
];

function stripTelegramBoilerplate(text) {
  let out = text;
  for (const marker of TG_BOILERPLATE_MARKERS) {
    const idx = out.indexOf(marker);
    if (idx !== -1) out = out.slice(0, idx);
  }
  // Once tags are stripped, hashtags are just plain "#word" tokens.
  out = out.replace(/#[^\s#]+/g, '');
  return out.replace(/\s+/g, ' ').trim();
}

// Parses one https://t.me/s/<channel>[?before=N] page into posts. Shared by
// both the normal single-page fetch and the backfill pagination below, so
// the extraction rules never drift between the two modes.
function parseTelegramPage(html, src) {
  const blocks = html
    .split(/(?=<div class="tgme_widget_message_wrap)/)
    .filter((b) => b.includes('data-post='));

  const posts = [];
  for (const block of blocks) {
    // Matching only this specific div means a preceding "Forwarded from ..."
    // marker (a sibling div, not a parent) is naturally excluded — forwarded
    // posts are handled by construction, no special-casing needed.
    const textMatch = block.match(
      /<div class="tgme_widget_message_text js-message_text" dir="auto">([\s\S]*?)<\/div>/
    );
    if (!textMatch) continue; // photo/video-only post, no caption — skip

    const text = stripTelegramBoilerplate(cleanText(textMatch[1]));
    if (!text) continue;

    const dateMatch = block.match(
      /<a[^>]*class="tgme_widget_message_date"[^>]*href="([^"]+)"[^>]*>\s*<time[^>]*datetime="([^"]+)"/
    );
    const postIdMatch = block.match(/data-post="([^"]+)"/);
    const link = dateMatch ? dateMatch[1] : postIdMatch ? `https://t.me/${postIdMatch[1]}` : null;
    if (!link) continue;

    const idParts = postIdMatch ? postIdMatch[1].split('/') : null;
    const numericId = idParts && idParts[1] ? parseInt(idParts[1], 10) : null;

    posts.push({
      // Telegram posts have no headline — use the text itself, truncated.
      title: text.slice(0, 100),
      link,
      guid: link,
      pub_date: dateMatch ? dateMatch[2] : null,
      snippet: text.slice(0, 600),
      source_id: src.id,
      source_name: src.name,
      language: src.language,
      _numeric_id: Number.isFinite(numericId) ? numericId : null
    });
  }
  return posts; // oldest-first within this page, same order t.me/s/ renders them
}

async function fetchTelegramPage(src, beforeId) {
  const url = `https://t.me/s/${src.channel}` + (beforeId ? `?before=${beforeId}` : '');
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: { 'user-agent': 'Mozilla/5.0' },
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
  if (response.statusCode < 200 || response.statusCode >= 300) {
    throw new Error(`HTTP ${response.statusCode}`);
  }
  return parseTelegramPage(String(response.body), src);
}

// Normal mode: one page, keep only the most recent max_items — unchanged
// from before backfill mode existed.
async function fetchTelegram(src) {
  const posts = await fetchTelegramPage.call(this, src, null);
  return posts.slice(-(src.max_items || 20));
}

// Backfill mode: paginate backward with ?before=<message id> until a page's
// oldest post is older than the window, the channel runs out of history, or
// the 5-page cap is hit (reported back as cap_hit so an incomplete backfill
// for a very active channel is visible, not silent).
async function fetchTelegramBackfill(src, cutoffDate) {
  const maxPages = 5;
  let before = null;
  let allPosts = [];
  let pagesFetched = 0;
  let reachedBoundary = false;

  for (let page = 0; page < maxPages; page++) {
    const posts = await fetchTelegramPage.call(this, src, before);
    pagesFetched++;
    if (!posts.length) {
      reachedBoundary = true; // start of the channel's history
      break;
    }

    allPosts = posts.concat(allPosts); // posts is oldest-first per page; prepend to keep overall oldest-first
    const oldestInPage = posts[0];

    if (oldestInPage.pub_date && new Date(oldestInPage.pub_date) <= cutoffDate) {
      reachedBoundary = true; // paginated back far enough
      break;
    }
    if (oldestInPage._numeric_id == null) {
      reachedBoundary = true; // can't page further without an id to pass as ?before=
      break;
    }
    before = oldestInPage._numeric_id;
  }

  const capHit = !reachedBoundary; // exhausted maxPages without reaching the boundary
  const withinWindow = allPosts.filter((p) => !p.pub_date || new Date(p.pub_date) > cutoffDate);
  return { posts: withinWindow, pages_fetched: pagesFetched, cap_hit: capHit };
}

// --- Main loop over config.sources ---
const entries = [];
const sourceResults = [];
const telegramFetchedIds = [];
const telegramLastFetch = state.telegram_last_fetch || {};

for (const src of config.sources) {
  if (!src.enabled) continue;

  if (src.type === 'email') {
    sourceResults.push({ id: src.id, name: src.name, type: src.type, fetched: 0, error: 'email source type not implemented yet' });
    continue;
  }

  try {
    if (src.type === 'rss') {
      const found = await fetchRss.call(this, src);
      entries.push(...found);
      sourceResults.push({ id: src.id, name: src.name, type: src.type, fetched: found.length, error: null });
    } else if (src.type === 'telegram') {
      if (isBackfill) {
        const result = await fetchTelegramBackfill.call(this, src, backfillCutoff);
        entries.push(...result.posts);
        sourceResults.push({
          id: src.id,
          name: src.name,
          type: src.type,
          fetched: result.posts.length,
          error: null,
          pages_fetched: result.pages_fetched,
          cap_hit: result.cap_hit
        });
        continue;
      }

      const last = telegramLastFetch[src.id];
      if (last && now - new Date(last).getTime() < TELEGRAM_FETCH_INTERVAL_MS) {
        sourceResults.push({ id: src.id, name: src.name, type: src.type, fetched: 0, error: null, skipped: 'fetched less than 24h ago' });
        continue;
      }
      const found = await fetchTelegram.call(this, src);
      telegramFetchedIds.push(src.id);
      entries.push(...found);
      sourceResults.push({ id: src.id, name: src.name, type: src.type, fetched: found.length, error: null });
    } else {
      sourceResults.push({ id: src.id, name: src.name, type: src.type, fetched: 0, error: `unknown source type "${src.type}"` });
    }
  } catch (e) {
    sourceResults.push({ id: src.id, name: src.name, type: src.type, fetched: 0, error: e.message });
  }
}

return [{
  json: {
    entries,
    source_results: sourceResults,
    telegram_fetched_ids: telegramFetchedIds,
    config,
    state,
    is_backfill: isBackfill
  }
}];

// Dedupes by URL/permalink and drops anything outside the relevant window,
// then (backfill only) caps the total candidate count.
//
// Normal mode (unchanged): window = since the last successful run (or the
// first-run lookback), and already-sent items are dropped via state's
// seen_ids.
//
// Backfill mode: window = config.eval.backfill_days back from now,
// ignoring last_run_at entirely; seen_ids is ignored too (the point is to
// re-score history, not skip anything already sent); a global cap of 300
// candidates applies, keeping the most recent ones when there's more than
// that within the window. Same-run duplicates (e.g. overlapping Telegram
// pages) are still deduped in both modes.
//
// A node with zero output items is skipped entirely by n8n, which would
// silently break the "always write a run log" requirement — so this node
// always returns exactly one item when there's nothing to score, tagged
// with `_empty`, carrying everything Finalize needs forward.
const input = items[0].json;
const config = input.config;
const state = input.state;
const isBackfill = input.is_backfill === true;
const all = input.entries || [];
const sourceResults = input.source_results || [];
const telegramFetchedIds = input.telegram_fetched_ids || [];
const fetchedCount = all.length;

if (!all.length) {
  return [{
    json: {
      _empty: true, config, state, is_backfill: isBackfill, fetched_count: 0,
      source_results: sourceResults, telegram_fetched_ids: telegramFetchedIds,
      within_window_by_source: {}
    }
  }];
}

let cutoff;
if (isBackfill) {
  const backfillDays = config.eval?.backfill_days ?? 30;
  cutoff = new Date(Date.now() - backfillDays * 24 * 3600 * 1000);
} else {
  cutoff = state.last_run_at
    ? new Date(state.last_run_at)
    : new Date(Date.now() - (config.run?.lookback_hours_on_first_run || 24) * 3600 * 1000);
}

const seen = new Set(isBackfill ? [] : (state.seen_ids || []));
const seenThisRun = new Set();
const withinWindowBySource = {};

const out = [];
for (const e of all) {
  const pub = e.pub_date ? new Date(e.pub_date) : null;
  const withinWindow = !pub || pub > cutoff;
  if (withinWindow) {
    withinWindowBySource[e.source_id] = (withinWindowBySource[e.source_id] || 0) + 1;
  } else {
    continue;
  }

  const key = e.guid || e.link; // dedupe by URL/permalink
  if (!key || seen.has(key) || seenThisRun.has(key)) continue;
  seenThisRun.add(key);

  out.push({
    json: {
      title: e.title,
      link: e.link,
      pub_date: e.pub_date,
      source_id: e.source_id,
      source_name: e.source_name,
      language: e.language,
      dedupe_key: key,
      snippet: e.snippet,
      config,
      state,
      is_backfill: isBackfill,
      fetched_count: fetchedCount,
      source_results: sourceResults,
      telegram_fetched_ids: telegramFetchedIds,
      within_window_by_source: withinWindowBySource
    }
  });
}

let finalOut = out;
if (isBackfill && out.length > 300) {
  finalOut = [...out]
    .sort((a, b) => new Date(b.json.pub_date || 0) - new Date(a.json.pub_date || 0))
    .slice(0, 300);
}

if (!finalOut.length) {
  return [{
    json: {
      _empty: true, config, state, is_backfill: isBackfill, fetched_count: fetchedCount,
      source_results: sourceResults, telegram_fetched_ids: telegramFetchedIds,
      within_window_by_source: withinWindowBySource
    }
  }];
}

return finalOut;

// Scores every surviving candidate against the rubric in config (not
// hardcoded here) using the Anthropic Messages API (model from
// config.llm.model). If nothing survived "Dedupe & Filter by Recency",
// this node is still called with exactly one `_empty` item — skip the API
// entirely and pass an all-zero result through, so Finalize always has
// something to log.
//
// CSV export (data/candidates.csv): normal mode appends, gated by
// config.eval.export_candidates_csv, and creates the file with a header
// only if it doesn't exist yet — unchanged from before backfill mode.
// Backfill mode always exports (regardless of that flag) and overwrites
// the file fresh at the start of the run, since the whole point of a
// backfill is to (re)build the labeling set from scratch.
const fs = require('fs');
const first = items[0].json;
const isBackfill = first.is_backfill === true;

if (items.length === 1 && first._empty) {
  return [{
    json: {
      kept: [],
      errors: [],
      scored_count: 0,
      fetched_count: first.fetched_count || 0,
      token_usage: { input_tokens: 0, output_tokens: 0 },
      source_results: first.source_results || [],
      telegram_fetched_ids: first.telegram_fetched_ids || [],
      within_window_by_source: first.within_window_by_source || {},
      score_distribution_by_source: {},
      config: first.config,
      state: first.state,
      is_backfill: isBackfill
    }
  }];
}

const cfg = first.config;
const state = first.state;
const rubric = cfg.rubric;
const threshold = cfg.threshold;
const apiKey = $env.LLM_API_KEY;
const exportCsv = isBackfill ? true : cfg.eval?.export_candidates_csv === true;
const csvPath = '/data/candidates.csv';

function shortHash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = (Math.imul(31, h) + str.charCodeAt(i)) | 0;
  }
  return (h >>> 0).toString(36);
}

function csvField(val) {
  const s = String(val ?? '');
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

if (isBackfill) {
  fs.mkdirSync('/data', { recursive: true });
  fs.writeFileSync(csvPath, 'id,source,date,title,snippet,url,model_score,label\n'); // overwrite at the start of every backfill run
} else if (exportCsv && !fs.existsSync(csvPath)) {
  fs.mkdirSync('/data', { recursive: true });
  fs.writeFileSync(csvPath, 'id,source,date,title,snippet,url,model_score,label\n');
}

function appendCandidateRow(c, modelScore) {
  if (!exportCsv) return;
  const row = [
    `${c.source_id}-${shortHash(c.dedupe_key)}`,
    c.source_id,
    c.pub_date || new Date().toISOString(),
    c.title,
    (c.snippet || '').slice(0, 300),
    c.link,
    modelScore ?? '',
    ''
  ].map(csvField).join(',');
  fs.appendFileSync(csvPath, row + '\n');
}

const kept = [];
const errors = [];
const scoreDistributionBySource = {};
let inTok = 0;
let outTok = 0;

for (const it of items) {
  const c = it.json;

  const promptText = `${rubric.instructions}\n\nTitle: ${c.title}\nText: ${c.snippet}`;

  const requestBody = {
    model: cfg.llm.model,
    max_tokens: 400,
    thinking: { type: 'disabled' },
    output_config: {
      format: {
        type: 'json_schema',
        schema: {
          type: 'object',
          properties: {
            // Anthropic structured outputs don't support numerical
            // constraints like minimum/maximum (400: "not supported") —
            // the 0-10 range is stated here and in the rubric text
            // instead, and enforced in code below (clamp + validity check).
            score: { type: 'integer', description: 'Relevance score from 0 (irrelevant) to 10 (must-read).' },
            summary: { type: 'string', description: 'One-line summary of the item, in the same language as the item.' },
            why_it_matters: { type: 'string', description: 'One-line reason this matters to the reader, in the same language as the item.' }
          },
          required: ['score', 'summary', 'why_it_matters'],
          additionalProperties: false
        }
      }
    },
    messages: [{ role: 'user', content: promptText }]
  };

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'content-type': 'application/json',
      'x-api-key': apiKey,
      'anthropic-version': '2023-06-01'
    },
    body: requestBody,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });

  if (response.statusCode < 200 || response.statusCode >= 300) {
    // Infra/auth-level failures (bad key, rate limit, outage) abort the
    // whole run so the error workflow fires — a single bad item shouldn't
    // silently eat the rest of the run, but a dead credential should be
    // loud, not logged as N quiet per-item errors.
    throw new Error(`Anthropic API error ${response.statusCode} for "${c.title}": ${JSON.stringify(response.body).slice(0, 300)}`);
  }

  const data = response.body;
  inTok += data.usage?.input_tokens || 0;
  outTok += data.usage?.output_tokens || 0;

  try {
    const text = data.content?.[0]?.text ?? '';
    const parsed = JSON.parse(text);

    // The schema can't enforce the 0-10 range (see note above), so a
    // missing or non-numeric score is treated as this item's error rather
    // than silently coerced into a number or defaulted to 0/kept.
    if (typeof parsed.score !== 'number' || Number.isNaN(parsed.score)) {
      errors.push(`Invalid score for "${c.title}": ${JSON.stringify(parsed.score)}`);
      appendCandidateRow(c, '');
      continue;
    }

    const score = Math.min(10, Math.max(0, parsed.score));
    appendCandidateRow(c, score);
    (scoreDistributionBySource[c.source_id] = scoreDistributionBySource[c.source_id] || []).push(score);

    if (score >= threshold) {
      kept.push({
        title: c.title,
        link: c.link,
        source_name: c.source_name,
        score,
        summary: parsed.summary,
        why_it_matters: parsed.why_it_matters,
        dedupe_key: c.dedupe_key
      });
    }
  } catch (e) {
    errors.push(`Parse error for "${c.title}": ${e.message}`);
    appendCandidateRow(c, '');
  }
}

return [{
  json: {
    kept,
    errors,
    scored_count: items.length,
    fetched_count: first.fetched_count,
    token_usage: { input_tokens: inTok, output_tokens: outTok },
    source_results: first.source_results || [],
    telegram_fetched_ids: first.telegram_fetched_ids || [],
    within_window_by_source: first.within_window_by_source || {},
    score_distribution_by_source: scoreDistributionBySource,
    config: cfg,
    state,
    is_backfill: isBackfill
  }
}];

// Normal mode (unchanged): persists the new dedupe state (including
// per-channel Telegram fetch times) + appends one line to the run log —
// with a per-source fetch breakdown — then builds the Telegram message
// text.
//
// Backfill mode: never writes state.json (seen_ids and telegram_last_fetch
// stay untouched — a backfill must not affect the next scheduled run) and
// never builds a Telegram message (has_items is forced false, so "Send
// Telegram Digest" no-ops). Instead it appends a backfill-flavored run log
// entry: per-source fetched/within-window/scored counts and score
// distribution, plus Telegram pagination cap-hit flags, token usage, and
// estimated cost.
const fs = require('fs');

const input = items[0].json;
const config = input.config;
const state = input.state;
const isBackfill = input.is_backfill === true;
const kept = input.kept || [];
const errors = input.errors || [];
const fetchedCount = input.fetched_count || 0;
const scoredCount = input.scored_count || 0;
const tokenUsage = input.token_usage || { input_tokens: 0, output_tokens: 0 };
const sourceResults = input.source_results || [];
const telegramFetchedIds = input.telegram_fetched_ids || [];

const nowIso = new Date().toISOString();
const costPerMTokIn = config.llm.cost_per_mtok_input ?? 0;
const costPerMTokOut = config.llm.cost_per_mtok_output ?? 0;
const cost =
  (tokenUsage.input_tokens / 1e6) * costPerMTokIn + (tokenUsage.output_tokens / 1e6) * costPerMTokOut;
const sourceErrors = sourceResults.filter((s) => s.error).map((s) => `${s.name}: ${s.error}`);

if (isBackfill) {
  const withinWindowBySource = input.within_window_by_source || {};
  const scoreDistBySource = input.score_distribution_by_source || {};

  const sourcesSummary = sourceResults.map((s) => ({
    id: s.id,
    name: s.name,
    type: s.type,
    fetched: s.fetched,
    within_window: withinWindowBySource[s.id] || 0,
    scored: (scoreDistBySource[s.id] || []).length,
    score_distribution: scoreDistBySource[s.id] || [],
    pages_fetched: s.pages_fetched,
    cap_hit: s.cap_hit,
    error: s.error
  }));

  const logEntry = {
    timestamp: nowIso,
    mode: 'backfill',
    backfill_days: config.eval?.backfill_days ?? 30,
    fetched: fetchedCount,
    scored: scoredCount,
    sources: sourcesSummary,
    input_tokens: tokenUsage.input_tokens,
    output_tokens: tokenUsage.output_tokens,
    estimated_cost_usd: Number(cost.toFixed(4)),
    errors: [...sourceErrors, ...errors]
  };
  fs.appendFileSync('/data/run-log.ndjson', JSON.stringify(logEntry) + '\n');

  return [{ json: { ...logEntry, has_items: false, is_backfill: true } }];
}

const newSeen = new Set(state.seen_ids || []);
for (const k of kept) newSeen.add(k.dedupe_key);
// Trim so the dedupe file doesn't grow forever.
const trimmedSeen = Array.from(newSeen).slice(-2000);

const telegramLastFetch = { ...(state.telegram_last_fetch || {}) };
for (const id of telegramFetchedIds) telegramLastFetch[id] = nowIso;

const newState = { seen_ids: trimmedSeen, last_run_at: nowIso, telegram_last_fetch: telegramLastFetch };
fs.mkdirSync('/data', { recursive: true });
fs.writeFileSync('/data/state.json', JSON.stringify(newState, null, 2));

const logEntry = {
  timestamp: nowIso,
  fetched: fetchedCount,
  scored: scoredCount,
  kept: kept.length,
  sources: sourceResults,
  input_tokens: tokenUsage.input_tokens,
  output_tokens: tokenUsage.output_tokens,
  estimated_cost_usd: Number(cost.toFixed(4)),
  errors: [...sourceErrors, ...errors]
};
fs.appendFileSync('/data/run-log.ndjson', JSON.stringify(logEntry) + '\n');

const sorted = [...kept].sort((a, b) => b.score - a.score);
const lines = sorted.map(
  (k, i) =>
    `${i + 1}. ${k.title} (${k.source_name}, score ${k.score}/10)\n${k.summary}\nWhy it matters: ${k.why_it_matters}\n${k.link}`
);

let messageText = kept.length
  ? `Music News Digest — ${kept.length} item(s)\n\n${lines.join('\n\n')}`
  : '';

// Telegram's hard message-length cap is 4096 characters.
if (messageText.length > 4000) {
  messageText = `${messageText.slice(0, 3980)}\n\n…(truncated)`;
}

return [{
  json: {
    ...logEntry,
    items: kept,
    has_items: kept.length > 0,
    message_text: messageText,
    chat_id: config.telegram.chat_id,
    is_backfill: false
  }
}];

// Nothing to send on a backfill run (by design) or a normal run that kept
// zero items — quietly do nothing rather than call the Telegram API with
// an empty message.
const input = items[0].json;
if (input.is_backfill || !input.has_items) {
  return [];
}

const token = $env.TELEGRAM_BOT_TOKEN;
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${token}/sendMessage`,
  headers: { 'content-type': 'application/json' },
  body: { chat_id: input.chat_id, text: input.message_text },
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true
});

if (response.statusCode < 200 || response.statusCode >= 300) {
  throw new Error(`Telegram API error ${response.statusCode}: ${JSON.stringify(response.body).slice(0, 300)}`);
}

const data = response.body;
return [{ json: { telegram_ok: data.ok === true } }];
